 for lab,color in [('Filtered-default','#c66032'),('Filtered-fit','#2679a4')]:
  a=np.load(O/f'{day}-{lo}-{lab}.npz');t=a['t']-a['t'][0];y=a['model'];truth=a['truth'];axs[0,col].plot(t,np.rad2deg(y[:,0]),color=color,label=lab.replace('Filtered-',''));axs[1,col].plot(t,np.rad2deg(y[:,2]-truth[0,2]),color=color)
 axs[0,col].plot(t,np.rad2deg(truth[:,0]),'k',label='flight');axs[1,col].plot(t,np.rad2deg(truth[:,2]-truth[0,2]),'k');axs[0,col].set_title(title);axs[1,col].set_xlabel('Replay time (s)')
