axs[0,0].set_ylabel('Payload bank (deg)');axs[1,0].set_ylabel('Heading change (deg)');axs[0,0].legend();fig.suptitle('Flight-specific PWM mapping + measured mass + filtered body rates\nModerate-turn fit evaluated on excluded maneuvers; rigid model only')
