 def v(k):return h[k][0][1]
 l=v('SERVO3_MAX')-v('SERVO3_MIN');r=v('SERVO4_MAX')-v('SERVO4_MIN');rows+=f'<tr><td>{name}</td><td>{v("SERVO3_MIN"):.0f}–{v("SERVO3_MAX"):.0f}</td><td>{v("SERVO4_MAX"):.0f}–{v("SERVO4_MIN"):.0f}</td><td>{l*np.pi*55/360*.1:.1f} / {r*np.pi*55/360*.1:.1f}</td></tr>'
